652	// strictCircuitObject decodes one committed circuit record's own member map,
653	// demanding a JSON object with exactly the known top-level fields once.
654	func strictCircuitObject(raw []byte, what string) (map[string]json.RawMessage, error) {
655		return strictObjectMembers(raw, what, persistCircuitFields)
656	}
