658	// strictObjectMembers decodes one committed record's own member map,
659	// demanding a JSON object without repeated keys. A non-nil allowed list
660	// restricts which keys may appear; nil allows any key. It scans only the
661	// record's own level: the envelope scanner already attributes a duplicated
662	// top-level key to this record, and nested values such as the constraint
663	// definition own their (more precise) strict decoders. Keys are compared
664	// after JSON unescaping, so a field repeated through a \uXXXX spelling is
665	// still a duplicate, even when both values are identical.
666	func strictObjectMembers(raw []byte, what string, allowedFields []string) (map[string]json.RawMessage, error) {
667		trimmed := bytes.TrimSpace(raw)
668		if len(trimmed) == 0 || trimmed[0] != '{' {
669			return nil, corruptf("%s must be a JSON object", what)
670		}
671		dec := json.NewDecoder(bytes.NewReader(trimmed))
672		dec.UseNumber()
673		open, err := dec.Token()
674		if err != nil || open != json.Delim('{') {
675			return nil, corruptf("%s must be a JSON object", what)
676		}
677		var allowed map[string]bool
678		if allowedFields != nil {
679			allowed = make(map[string]bool, len(allowedFields))
680			for _, f := range allowedFields {
681				allowed[f] = true
682			}
683		}
684		members := make(map[string]json.RawMessage)
685		for dec.More() {
686			keyTok, err := dec.Token()
687			if err != nil {
688				return nil, corruptf("%s is not valid JSON: %v", what, err)
689			}
690			key, ok := keyTok.(string)
691			if !ok {
692				return nil, corruptf("%s is not valid JSON", what)
693			}
694			if allowed != nil && !allowed[key] {
695				return nil, corruptf("%s has unknown field %q", what, key)
696			}
697			if _, repeated := members[key]; repeated {
698				return nil, corruptf("%s contains duplicate field %q", what, key)
699			}
700			var value json.RawMessage
701			if err := dec.Decode(&value); err != nil {
702				return nil, corruptf("%s is not valid JSON: %v", what, err)
703			}
704			members[key] = value
705		}
706		if closeTok, err := dec.Token(); err != nil || closeTok != json.Delim('}') {
707			return nil, corruptf("%s is not valid JSON", what)
708		}
709		if _, err := dec.Token(); err != io.EOF {
710			return nil, corruptf("%s is not valid JSON: trailing data after the object", what)
711		}
712		return members, nil
713	}
