720	type persistJob struct {
721		ID       string `json:"id"`
722		Circuit  string `json:"circuit"`
723		Version  int    `json:"version"`
724		Kind     string `json:"kind"`
725		Attempt  int    `json:"attempt"`
726		Artifact string `json:"artifact,omitempty"`
