732	// compiledHashKey is the canonical spelling of a job record's
733	// compiled-artifact binding field.
734	const compiledHashKey = "compiled_hash"
735	
736	// isASCIIFoldOf reports whether key names canonical under an ASCII-only
737	// letter-case fold: the two must have the same byte length and every byte
738	// must match after mapping A-Z onto a-z. JSON keys arrive here already
739	// unescaped, so a key written with a \uXXXX escape for an ASCII letter (say
740	// u0076 for "v") is judged on its decoded spelling too. A key of a different
741	// length, or one that needs a non-ASCII rune to match, returns false — use
742	// strings.EqualFold to detect those non-ASCII lookalikes separately.
743	func isASCIIFoldOf(key, canonical string) bool {
744		if len(key) != len(canonical) {
745			return false
746		}
747		for i := 0; i < len(key); i++ {
748			c := key[i]
749			if c >= 'A' && c <= 'Z' {
750				c += 'a' - 'A'
751			}
752			if c != canonical[i] {
753				return false
754			}
755		}
756		return true
757	}
758	
759	// isCompiledHashKey reports whether key is an accepted spelling of the
760	// compiled-artifact binding field: only "compiled_hash" itself and ASCII
761	// letter-case variants such as "COMPILED_HASH" or "CoMpIlEd_HaSh". Keys are
762	// already JSON-unescaped at this point, so an escaped spelling of any of
763	// these forms lands here too. Non-ASCII letters are never folded here.
764	func isCompiledHashKey(key string) bool {
765		return isASCIIFoldOf(key, compiledHashKey)
766	}
767	
768	// jobVersionKey is the canonical spelling of a job record's pinned circuit
769	// version field. The version names the frozen circuit — and thereby its
770	// trusted setup and compiled artifact — the job belongs to.
771	const jobVersionKey = "version"
772	
773	// compiledHashLookalike reports a member key encoding/json would match onto
774	// the binding field's struct tag yet which is not an accepted ASCII spelling
775	// (isCompiledHashKey). Struct-tag matching in encoding/json folds with the
776	// Unicode simple case-folding rules (bytes.EqualFold), so a non-ASCII
777	// lookalike — "compiled_haſh" with U+017F long s, whether written directly
778	// or as the JSON escape u017f — silently fills CompiledHash and would let a
779	// damaged binding (null above all) read as unbound, then vanish on the next
780	// commit. Such a key is damage, regardless of its value or of a correctly
781	// spelled sibling key being present. Several aliases are reported in
782	// lexicographic order so the message is stable.
783	func compiledHashLookalike(members map[string]json.RawMessage) string {
784		var aliases []string
785		for key := range members {
786			if isCompiledHashKey(key) {
787				continue
788			}
789			if strings.EqualFold(key, compiledHashKey) {
790				aliases = append(aliases, key)
791			}
792		}
793		if len(aliases) == 0 {
794			return ""
795		}
796		sort.Strings(aliases)
797		return aliases[0]
798	}
