800	// Strict decoding of the compiled-artifact binding on a committed job record.
801	//
802	// compiled_hash is a field whose presence is meaningful: records written
803	// before bindings existed simply omit it, and an explicit "" is the unbound
804	// state. But once the key appears its value must be a JSON string. A null is
805	// not "no binding" — it is damage to a binding the record claims to carry,
806	// and so is a number, boolean, array or object in its place. Reading either
807	// as the zero string would silently turn a bound job into an unbound one
808	// (and the next commit would drop the field entirely), so the read is
809	// refused as data corruption instead. A repeated key — including one
810	// repeated through JSON string escapes, even with identical values — is
811	// likewise refused rather than resolved to its last value. A legal non-empty
812	// string keeps being matched against the pinned version's artifact by
813	// validateEnvelope, exactly as written.
814	//
815	// The field is recognized under any ASCII letter-case spelling, so a record
816	// carrying "COMPILED_HASH" (or any mixed-case form, escaped or not) is the
817	// same binding and follows the same rules: a single such key is read with
818	// the full string validation above, and two spellings of the field on one
819	// record — even with byte-identical values — are a duplicate binding and
820	// corrupt the read rather than being resolved by key order.
821	//
822	// Non-ASCII spellings are not accepted even though encoding/json itself
823	// would fold them onto the field: its struct-tag matching uses Unicode case
824	// folding, under which "compiled_haſh" (U+017F long s, written directly or
825	// as the JSON escape u017f) names CompiledHash just like "compiled_hash".
826	// Such a lookalike is damage to the binding the record claims to carry and
827	// is refused whatever its value — null, a legal hash or an explicit "" —
828	// and even when a correctly spelled "compiled_hash" sits beside it, in
829	// either key order and whether the two values agree. The damaged binding
830	// must never read as an unbound job and disappear on the next commit.
831	//
832	// The pinned version field is held to a uniqueness rule of its own. The
833	// "version" the record writes is the sole authority for which frozen circuit
834	// — and therefore which trusted setup and compiled artifact — the job belongs
835	// to. Every spelling the ordinary decode below fills Version from counts as
836	// that one field: canonical "version", an ASCII letter-case variant such as
837	// "VERSION", and, since struct-tag matching folds with Unicode case rules,
838	// the long-s "verſion" (U+017F, direct or u017f-escaped); keys are compared
839	// after JSON unescaping, so an escaped spelling lands here too. Two such
840	// spellings on one record are refused as data corruption whether the values
841	// agree or differ, whether both values are legal versions, and even when
842	// unrelated fields are interleaved between them: encoding/json would keep
843	// the last value, so without this check a job could be read against a
844	// different frozen, set-up version purely from key order. A non-ASCII
845	// "verſion" is refused only when another recognized spelling sits beside it;
846	// appearing by itself it is the single version field and keeps the current
847	// reading (the ordinary decode folds it onto Version). A single spelling of
848	// any kind keeps its current value and spelling compatibility, and an illegal
849	// single value — a string, a float, null, or a non-positive version — is
850	// rejected exactly as before, by the decode or validateEnvelope.
851	//
852	// Only these two job fields are judged here; every other field keeps the
853	// ordinary struct decoding.
854	func (j *persistJob) UnmarshalJSON(raw []byte) error {
855		const what = "stored job record"
856		if string(bytes.TrimSpace(raw)) == "null" {
857			return corruptf("%s must be a JSON object, not null", what)
858		}
859		// Name the job up front, best-effort, so a failure of the strict member
860		// walk below — an exact duplicate key is rejected there before a member map
861		// exists — still locates the record it came from. This probe only labels
862		// errors: a missing, non-string or undecodable id leaves the generic name,
863		// and the id is decoded for real by the ordinary pass later.
864		where := what
865		var idProbe struct {
866			ID string `json:"id"`
867		}
868		if err := json.Unmarshal(raw, &idProbe); err == nil && idProbe.ID != "" {
869			where = fmt.Sprintf("stored job record %q", idProbe.ID)
870		}
871		members, err := strictObjectMembers(raw, where, nil)
872		if err != nil {
873			return err
874		}
875		// Reject a non-ASCII spelling that encoding/json's Unicode-folded tag
876		// matching would silently read as this field ("compiled_haſh" with long
877		// s, directly written or ſ-escaped), whatever its value and whether
878		// or not a correctly spelled key accompanies it. It must never be ignored
879		// as an unknown member, which would let a damaged binding read unbound.
880		if alias := compiledHashLookalike(members); alias != "" {
881			return corruptf("%s carries the binding field %q under non-ASCII spelling %q; such a lookalike spelling is data corruption",
882				where, compiledHashKey, alias)
883		}
884		// Every spelling the ordinary read below would fill Version from is one
885		// version field: canonical "version", an ASCII letter-case variant, or a
886		// JSON-escaped spelling that unescapes onto either — and, because
887		// encoding/json's struct-tag matching folds with Unicode case rules
888		// (strings.EqualFold), the long-s "verſion" (U+017F, direct or u017f-
889		// escaped) too. The pinned version selects the frozen circuit, its trusted
890		// setup and its artifact, so a record carrying two such spellings is
891		// ambiguous: encoding/json keeps the last value, which would let the
892		// binding flip depending on key order (or let an unhashed job read against
893		// a different frozen, set-up version). Whatever the two values are — equal
894		// or different, both legal — and even with unrelated fields interleaved
895		// between them, the whole record is refused rather than resolved by order.
896		// A long-s spelling counts here only beside another recognized spelling;
897		// standing alone it is the single version field and keeps the current
898		// reading handled below.
899		var versionKeys []string
900		for key := range members {
901			if strings.EqualFold(key, jobVersionKey) {
902				versionKeys = append(versionKeys, key)
903			}
904		}
905		if len(versionKeys) > 1 {
906			sort.Strings(versionKeys)
907			quoted := make([]string, len(versionKeys))
908			for i, k := range versionKeys {
909				quoted[i] = strconv.Quote(k)
910			}
911			return corruptf("%s carries the pinned version field %q more than once (as %s)",
912				where, jobVersionKey, strings.Join(quoted, ", "))
913		}
914		// With zero or one recognized spelling, the ordinary decode below already
915		// yields the current value: a single canonical/ASCII/long-s spelling folds
916		// onto Version, and a missing version reads as 0 and is rejected by
917		// validateEnvelope as a job bound to an unknown circuit. Illegal single
918		// values (a string, a float, null, zero or negative) keep being rejected by
919		// that same decode or the envelope validation, so nothing is picked here.
920		// Every accepted spelling of the binding field counts as the same one
921		// field; the record may carry it at most once, however it is capitalized.
922		var bindingKeys []string
923		for key := range members {
924			if isCompiledHashKey(key) {
925				bindingKeys = append(bindingKeys, key)
926			}
927		}
928		if len(bindingKeys) > 1 {
929			sort.Strings(bindingKeys)
930			quoted := make([]string, len(bindingKeys))
931			for i, k := range bindingKeys {
932				quoted[i] = strconv.Quote(k)
933			}
934			return corruptf("%s carries the binding field %q more than once (as %s)",
935				where, compiledHashKey, strings.Join(quoted, ", "))
936		}
937		compiledHash := ""
938		hasBinding := false
939		if len(bindingKeys) == 1 {
940			hash, err := storedRecordShape.string(members[bindingKeys[0]], where+` field "compiled_hash"`)
941			if err != nil {
942				return err
943			}
944			compiledHash, hasBinding = hash, true
945		}
946		type plainJob persistJob
947		var decoded plainJob
948		if err := json.Unmarshal(raw, &decoded); err != nil {
949			return corruptf("%s is not valid JSON: %v", what, err)
950		}
951		if hasBinding {
952			decoded.CompiledHash = compiledHash
953		}
954		*j = persistJob(decoded)
955		return nil
956	}
