958	// Store is a persistent workbench backed by one local data directory.
959	//
960	// All operations are safe for concurrent use by multiple goroutines and by
961	// several processes pointed at the same directory: an in-process mutex plus a
962	// process-shared flock serialize commits, and every commit is an atomic
963	// temp-file/fsync/rename replacement. Open the directory with Open and call
964	// Close when done.
965	type Store struct {
966		dir  string
967		mu   sync.Mutex
968		lock *os.File
969	
970		data envelope
971	}
972	
973	// Open opens (creating if needed) the workbench data in dir. If the
974	// directory does not exist it is created. Existing committed data is loaded
975	// and fully validated before Open returns; on a corrupt, truncated or
976	// unsupported-format file Open returns an error wrapping ErrDataCorrupt and
977	// leaves every file in the directory untouched.
978	func Open(dir string) (*Store, error) {
979		if dir == "" {
980			return nil, invalidf("data directory must not be empty")
981		}
982		if err := os.MkdirAll(dir, 0o755); err != nil {
983			return nil, fmt.Errorf("cannot create data directory %q: %w", dir, err)
984		}
985		lockPath := filepath.Join(dir, dirLockFile)
986		lock, err := os.OpenFile(lockPath, os.O_RDWR|os.O_CREATE, 0o644)
987		if err != nil {
988			return nil, fmt.Errorf("cannot open lock file in %q: %w", dir, err)
989		}
990		// Serialize against other processes while we read / validate.
991		if err := lockExclusive(lock); err != nil {
992			lock.Close()
993			return nil, fmt.Errorf("cannot lock data directory %q: %w", dir, err)
994		}
995	
996		s := &Store{dir: dir, lock: lock}
997		if err := s.loadLocked(); err != nil {
998			unlockLock(lock)
999			lock.Close()
1000			return nil, err
1001		}
1002		// The lock is taken again per operation; holding it for the store's
1003		// lifetime would forbid two open handles on one directory.
1004		if err := unlockLock(lock); err != nil {
1005			lock.Close()
1006			return nil, fmt.Errorf("cannot release open lock on %q: %w", dir, err)
1007		}
1008		return s, nil
1009	}
1010	
1011	// Close releases the directory lock. It does not discard committed data.
1012	func (s *Store) Close() error {
1013		s.mu.Lock()
1014		defer s.mu.Unlock()
1015		if s.lock == nil {
1016			return nil
1017		}
1018		var first error
1019		if err := unlockLock(s.lock); err != nil {
1020			first = err
1021		}
1022		if err := s.lock.Close(); err != nil && first == nil {
1023			first = err
1024		}
1025		s.lock = nil
1026		return first
1027	}
1028	
1029	// Dir reports the data directory backing the store.
1030	func (s *Store) Dir() string { return s.dir }
1031	
1032	func (s *Store) dataPath() string { return filepath.Join(s.dir, dirDataFile) }
1033	func (s *Store) tmpPath() string  { return filepath.Join(s.dir, dirTmpFile) }
1034	
1035	// loadLocked reads and validates the committed file. Caller must hold the
1036	// exclusive flock; the in-process mutex is taken by the public Open path.
1037	func (s *Store) loadLocked() error {
1038		raw, err := os.ReadFile(s.dataPath())
1039		if errors.Is(err, os.ErrNotExist) {
1040			s.data = envelope{Format: FormatVersion}
1041			return nil
1042		}
1043		if err != nil {
1044			return fmt.Errorf("cannot read data file %q: %w", s.dataPath(), err)
1045		}
1046		if len(strings.TrimSpace(string(raw))) == 0 {
1047			return corruptf("data file %q is empty or truncated; refusing to treat it as a new directory", s.dataPath())
1048		}
1049	
1050		var env envelope
1051		if err := json.Unmarshal(raw, &env); err != nil {
1052			// Shape failures surfaced by the persisted-definition decoders are
1053			// integrity failures, not JSON syntax errors; report their detail
1054			// instead of the generic "not valid JSON" wording.
1055			var se StoreError
1056			if errors.As(err, &se) && se.Kind == ErrDataCorrupt.Kind {
1057				return corruptf("data file %q failed integrity validation: %s; original file left in place", s.dataPath(), se.Detail)
1058			}
1059			return corruptf("data file %q is not valid JSON (%v); original file left in place", s.dataPath(), err)
1060		}
1061		if env.Format == 0 {
1062			return corruptf("data file %q has no format version; original file left in place", s.dataPath())
1063		}
1064		if env.Format != FormatVersion {
1065			return corruptf("data file %q uses unsupported format version %d (this build supports %d); original file left in place",
1066				s.dataPath(), env.Format, FormatVersion)
1067		}
1068		if err := validateEnvelope(env); err != nil {
1069			return corruptf("data file %q failed integrity validation: %v; original file left in place", s.dataPath(), err)
1070		}
1071		s.data = env
1072		return nil
1073	}
1074	
1075	// commitLocked writes the pending state atomically: temp file → fsync →
1076	// rename → fsync directory. Caller must hold both the in-process mutex and
1077	// the exclusive flock; all in-memory mutations must already have happened and
1078	// been rule-checked, so a failure here occurs before any success is reported.
1079	func (s *Store) commitLocked() error {
1080		s.data.Format = FormatVersion
1081		// Stable output: records are stored sorted so files are deterministic.
1082		sortEnvelope(&s.data)
1083	
1084		payload, err := json.MarshalIndent(&s.data, "", "  ")
1085		if err != nil {
1086			return fmt.Errorf("cannot encode data: %w", err)
1087		}
1088		payload = append(payload, '\n')
1089	
1090		tmp := s.tmpPath()
1091		f, err := os.OpenFile(tmp, os.O_RDWR|os.O_CREATE|os.O_TRUNC, 0o644)
1092		if err != nil {
1093			return fmt.Errorf("cannot stage write in %q: %w", s.dir, err)
1094		}
1095		if _, err := f.Write(payload); err != nil {
1096			f.Close()
1097			os.Remove(tmp)
1098			return fmt.Errorf("cannot write staged data: %w", err)
1099		}
1100		if err := f.Sync(); err != nil {
1101			f.Close()
1102			os.Remove(tmp)
1103			return fmt.Errorf("cannot flush staged data: %w", err)
1104		}
1105		if err := f.Close(); err != nil {
1106			os.Remove(tmp)
1107			return fmt.Errorf("cannot finish staged data: %w", err)
1108		}
1109		if err := os.Rename(tmp, s.dataPath()); err != nil {
1110			os.Remove(tmp)
1111			return fmt.Errorf("cannot commit data file: %w", err)
1112		}
1113		if err := syncDir(s.dir); err != nil {
1114			// The rename already happened; lack of dir fsync only weakens crash
1115			// durability, never correctness of what is visible now.
1116			return nil
1117		}
1118		return nil
1119	}
1120	
1121	// withLock runs fn under the in-process mutex and an exclusive flock, then
1122	// atomically commits when fn requests it. The on-disk state is re-read after
1123	// acquiring the lock, so concurrent commits from another process or another
1124	// handle are always observed. Operations validate before mutating; a rejected
1125	// operation (commit=false or an error) writes nothing and leaves committed
1126	// state unchanged.
1127	func (s *Store) withLock(fn func() (commit bool, err error)) error {
1128		s.mu.Lock()
1129		defer s.mu.Unlock()
1130		if s.lock == nil {
1131			return invalidf("store is closed")
1132		}
1133		if err := lockExclusive(s.lock); err != nil {
1134			return fmt.Errorf("cannot lock data directory: %w", err)
1135		}
1136		defer unlockLock(s.lock)
1137	
1138		if err := s.loadLocked(); err != nil {
1139			return err
1140		}
1141		commit, err := fn()
1142		if err != nil {
1143			return err
1144		}
1145		if !commit {
1146			return nil
1147		}
1148		return s.commitLocked()
1149	}
1150	
1151	// withLockRead runs fn under a shared flock over freshly reloaded state.
1152	func (s *Store) withLockRead(fn func() error) error {
1153		s.mu.Lock()
1154		defer s.mu.Unlock()
1155		if s.lock == nil {
1156			return invalidf("store is closed")
1157		}
1158		if err := lockShared(s.lock); err != nil {
1159			return fmt.Errorf("cannot lock data directory: %w", err)
1160		}
1161		defer unlockLock(s.lock)
1162		if err := s.loadLocked(); err != nil {
1163			return err
1164		}
1165		return fn()
1166	}
1167	
1168	func sortEnvelope(env *envelope) {
1169		sort.Slice(env.Circuits, func(i, j int) bool {
1170			if env.Circuits[i].Name != env.Circuits[j].Name {
1171				return env.Circuits[i].Name < env.Circuits[j].Name
1172			}
1173			return env.Circuits[i].Version < env.Circuits[j].Version
1174		})
1175		sort.Slice(env.Setups, func(i, j int) bool {
1176			if env.Setups[i].Name != env.Setups[j].Name {
1177				return env.Setups[i].Name < env.Setups[j].Name
1178			}
1179			return env.Setups[i].Version < env.Setups[j].Version
1180		})
1181		sort.Slice(env.Jobs, func(i, j int) bool { return env.Jobs[i].ID < env.Jobs[j].ID })
1182		sort.Slice(env.Artifacts, func(i, j int) bool {
1183			if env.Artifacts[i].Name != env.Artifacts[j].Name {
1184				return env.Artifacts[i].Name < env.Artifacts[j].Name
1185			}
1186			return env.Artifacts[i].Version < env.Artifacts[j].Version
1187		})
1188	}
1189	
1190	// validateEnvelope re-checks every invariant on load so a tampered or
1191	// hand-edited file cannot bypass the domain rules.
1192	func validateEnvelope(env envelope) error {
1193		seenCircuit := make(map[[2]string]bool)
1194		circuitOK := make(map[[2]string]bool)
1195		for i, c := range env.Circuits {
1196			key := [2]string{c.Name, itoa(c.Version)}
1197			if c.Name == "" || strings.TrimSpace(c.Name) == "" {
1198				return fmt.Errorf("circuit #%d has an empty or blank name", i+1)
1199			}
1200			if c.Version <= 0 {
1201				return fmt.Errorf("circuit %q version %d is not a positive integer", c.Name, c.Version)
1202			}
1203			if seenCircuit[key] {
1204				return fmt.Errorf("circuit %q version %d appears more than once", c.Name, c.Version)
1205			}
1206			seenCircuit[key] = true
1207			if c.Constraints <= 0 {
1208				return fmt.Errorf("circuit %q v%d: constraints must be > 0", c.Name, c.Version)
1209			}
1210			if c.PublicInputs < 0 || c.PrivateInputs < 0 {
1211				return fmt.Errorf("circuit %q v%d: input counts must not be negative", c.Name, c.Version)
1212			}
1213			// The same representability rule the write path enforces: wire 0 plus
1214			// every declared input must fit inside the platform's int. A record
1215			// beyond that bound can never have been written by this build and
1216			// cannot be checked safely, so the directory is corrupt rather than
1217			// silently narrowed or read with a wrapped-around layout.
1218			if !inputLayoutRepresentable(c.PublicInputs, c.PrivateInputs) {
1219				return fmt.Errorf("circuit %q v%d: input layout is not representable: 1 constant wire + %d public + %d private inputs exceeds the platform limit of %d wires",
1220					c.Name, c.Version, c.PublicInputs, c.PrivateInputs, maxInputWires)
1221			}
1222			if c.Definition != nil {
1223				if err := validatePersistDefinition(c.Name, c.Version, c.Constraints, c.PublicInputs, c.PrivateInputs, c.Definition); err != nil {
1224					return err
1225				}
1226			}
1227			circuitOK[key] = true
1228		}
1229		seenSetup := make(map[[2]string]bool)
1230		for i, p := range env.Setups {
1231			key := [2]string{p.Name, itoa(p.Version)}
1232			if !circuitOK[key] {
1233				return fmt.Errorf("setup #%d belongs to unknown circuit %q v%d", i+1, p.Name, p.Version)
1234			}
1235			c := findPersistCircuit(env.Circuits, p.Name, p.Version)
1236			if c == nil || !c.Frozen {
1237				return fmt.Errorf("setup belongs to non-frozen circuit %q v%d", p.Name, p.Version)
1238			}
1239			if seenSetup[key] {
1240				return fmt.Errorf("setup for %q v%d appears more than once", p.Name, p.Version)
1241			}
1242			seenSetup[key] = true
1243		}
1244		seenJob := make(map[string]bool)
1245		for i, j := range env.Jobs {
1246			if j.ID == "" || strings.TrimSpace(j.ID) == "" {
1247				return fmt.Errorf("job #%d has an empty or blank id", i+1)
1248			}
1249			if seenJob[j.ID] {
1250				return fmt.Errorf("job %q appears more than once", j.ID)
1251			}
1252			seenJob[j.ID] = true
1253			if j.Kind != "prove" {
1254				return fmt.Errorf("job %q has unsupported kind %q", j.ID, j.Kind)
1255			}
1256			if j.Attempt <= 0 {
1257				return fmt.Errorf("job %q: attempt must be a positive integer", j.ID)
1258			}
1259			key := [2]string{j.Circuit, itoa(j.Version)}
1260			if !circuitOK[key] {
1261				return fmt.Errorf("job %q binds to unknown circuit %q v%d", j.ID, j.Circuit, j.Version)
1262			}
1263			c := findPersistCircuit(env.Circuits, j.Circuit, j.Version)
1264			if c == nil || !c.Frozen {
1265				return fmt.Errorf("job %q binds to non-frozen circuit %q v%d", j.ID, j.Circuit, j.Version)
1266			}
1267			if !seenSetup[key] {
1268				return fmt.Errorf("job %q binds to circuit %q v%d without a trusted setup", j.ID, j.Circuit, j.Version)
1269			}
1270			// A recorded compiled-artifact binding must still resolve against the
1271			// pinned version's artifact; a dangling or mismatched binding makes
1272			// the file unreadable rather than silently dropping the binding.
1273			if j.CompiledHash != "" {
1274				artifact := findArtifact(env.Artifacts, j.Circuit, j.Version)
1275				if artifact == nil {
1276					return fmt.Errorf("job %q binds to compiled artifact of %q v%d which is missing", j.ID, j.Circuit, j.Version)
1277				}
1278				if artifact.Hash != j.CompiledHash {
1279					return fmt.Errorf("job %q compiled hash %q does not match the artifact of %q v%d (hash %q)",
1280						j.ID, j.CompiledHash, j.Circuit, j.Version, artifact.Hash)
1281				}
1282			}
1283		}
1284		seenArtifact := make(map[[2]string]bool)
1285		for i, a := range env.Artifacts {
1286			key := [2]string{a.Name, itoa(a.Version)}
1287			if !circuitOK[key] {
1288				return fmt.Errorf("artifact #%d belongs to unknown circuit %q v%d", i+1, a.Name, a.Version)
1289			}
1290			c := findPersistCircuit(env.Circuits, a.Name, a.Version)
1291			if c == nil || !c.Frozen {
1292				return fmt.Errorf("artifact belongs to non-frozen circuit %q v%d", a.Name, a.Version)
1293			}
1294			if seenArtifact[key] {
1295				return fmt.Errorf("artifact for %q v%d appears more than once", a.Name, a.Version)
1296			}
1297			seenArtifact[key] = true
1298			if c.Definition == nil {
1299				return fmt.Errorf("artifact for %q v%d has no constraint definition", a.Name, a.Version)
1300			}
1301			if a.Constraints != c.Constraints {
1302				return fmt.Errorf("artifact for %q v%d constraint count %d disagrees with the version's %d",
1303					a.Name, a.Version, a.Constraints, c.Constraints)
1304			}
1305			def, err := definitionFromPersist(*c.Definition, c.PublicInputs, c.PrivateInputs)
1306			if err != nil {
1307				return fmt.Errorf("artifact for %q v%d cannot be checked against its definition: %w", a.Name, a.Version, err)
1308			}
1309			if int64(a.Modulus) != def.modulus || len(def.constraints) != a.Constraints {
1310				return fmt.Errorf("artifact for %q v%d is inconsistent with its stored definition", a.Name, a.Version)
1311			}
1312			wantHash := artifactHash(a.Name, a.Version, def)
1313			if a.Hash != wantHash {
1314				return fmt.Errorf("artifact for %q v%d hash %q does not recompute from the definition (want %q)",
1315					a.Name, a.Version, a.Hash, wantHash)
1316			}
1317		}
1318		return nil
1319	}
1320	
1321	// validatePersistDefinition re-validates a stored definition against its
1322	// version's declared counts: prime modulus, in-range wires and an exact
1323	// constraint count match.
1324	func validatePersistDefinition(name string, version, constraints, public, private int, def *persistDefinition) error {
1325		parsed, err := definitionFromPersist(*def, public, private)
1326		if err != nil {
1327			return fmt.Errorf("circuit %q v%d has a corrupt constraint definition: %w", name, version, err)
1328		}
1329		if !parsed.compatibleWith(constraints, public, private) {
1330			return fmt.Errorf("circuit %q v%d definition is incompatible with its declared counts", name, version)
1331		}
1332		return nil
1333	}
1334	
1335	func findPersistCircuit(cs []persistCircuit, name string, version int) *persistCircuit {
1336		for i := range cs {
1337			if cs[i].Name == name && cs[i].Version == version {
1338				return &cs[i]
1339			}
1340		}
1341		return nil
1342	}
1343	
1344	func itoa(v int) string { return fmt.Sprintf("%d", v) }
